package com.lrh.healthvivo.link

import java.util.UUID

/**
 * Vitality Link wire format, protocol version 1 — the phone half of
 * `watch/src/lib/link/frames.mjs`.
 *
 * The two implementations must stay byte-for-byte identical. `LinkVectorsTest` asserts that this
 * file reproduces the exact bytes generated by the watch implementation, so a change here without
 * the matching change there fails the build.
 *
 * Physical layer: one GATT service with a single characteristic that is both readable and
 * writable. Every phone frame is one acknowledged ATT write of at most 20 bytes (the default
 * MTU 23 payload), and every reply is read back from the same characteristic.
 */
internal object LinkFrames {
    /**
     * The service and characteristic UUIDs are deliberately the ones the validated diagnostic link
     * used. Android caches a bonded device's whole attribute database, and this phone/watch pair is
     * already on record reading a stale service catalogue when a new UUID was introduced (see
     * docs/DIRECT_LINK_DEVICE_VALIDATION.md). Reusing the cached pair means an existing install
     * finds the service on the very first discovery; a new UUID would strand every already-paired
     * phone until the cache is invalidated, which no public Android API can do.
     *
     * The trade-off is that the standalone diagnostic probe app must not run at the same time as
     * the production watch app, because they publish the same service.
     */
    val SERVICE: UUID = UUID.fromString("fa954400-48d6-4a12-b74b-4c5b5170360e")
    val CHARACTERISTIC: UUID = UUID.fromString("fa954401-48d6-4a12-b74b-4c5b5170360e")

    const val PROTOCOL_VERSION = 1

    /** Phone to watch operations. */
    const val OP_BEGIN = 1
    const val OP_DATA = 2
    const val OP_END = 3
    const val OP_POLL = 4
    const val OP_RELEASE = 5
    const val OP_RESET = 6

    /** BEGIN kinds: 1 resumes a saved secret, 2 carries an encrypted body, 3 enrols a new secret. */
    const val KIND_HELLO = 1
    const val KIND_BODY = 2
    const val KIND_ENROLL = 3

    /** Receipt states; the table lives in docs/LINK_PROTOCOL.md. */
    const val STATE_OPEN = 1
    const val STATE_READY = 2
    const val STATE_RECEIVING = 3
    const val STATE_SAVED = 4
    const val STATE_FAILED = 5
    const val STATE_REJECTED = 6
    const val STATE_BUSY = 7
    const val STATE_REPLY = 8

    const val GREETING_MARK = 0xd6
    const val REPLY_MARK = 0xd8
    const val FAILURE_MARK = 5

    const val ATT_PAYLOAD = 20
    const val BEGIN_SIZE = 14
    const val END_SIZE = 9
    const val DATA_HEADER = 9
    const val REPLY_HEADER = 9
    const val DATA_PAYLOAD = ATT_PAYLOAD - DATA_HEADER
    const val REPLY_PAYLOAD = ATT_PAYLOAD - REPLY_HEADER
    const val MAX_BODY = 200 * 1024
    const val MAX_REPLY = 32767
    const val MIN_POLL = 1
    const val MAX_POLL = REPLY_PAYLOAD
    const val ENROLL_SIZE = 32 + 16 + 32
    const val HELLO_SIZE = 16 + 32
    const val RECEIPT_SIZE = 20
    const val GREETING_SIZE = 20

    const val REQUEST_FLAG = 0x8000
    const val FLAG_MASK = 0x7fff

    fun begin(id: Int, kind: Int, length: Int, crc: Int) = LinkBytes.concat(
        byteArrayOf(OP_BEGIN.toByte()), LinkBytes.u32(id), byteArrayOf(kind.toByte()),
        LinkBytes.u32(length), LinkBytes.u32(crc))

    fun data(id: Int, offset: Int, chunk: ByteArray) = LinkBytes.concat(
        byteArrayOf(OP_DATA.toByte()), LinkBytes.u32(id), LinkBytes.u32(offset), chunk)

    fun end(id: Int, crc: Int) = LinkBytes.concat(byteArrayOf(OP_END.toByte()), LinkBytes.u32(id), LinkBytes.u32(crc))

    fun poll(id: Int, offset: Int, size: Int) = LinkBytes.concat(
        byteArrayOf(OP_POLL.toByte()), LinkBytes.u32(id), LinkBytes.u32(offset), byteArrayOf(size.toByte()))

    fun release(id: Int) = LinkBytes.concat(byteArrayOf(OP_RELEASE.toByte()), LinkBytes.u32(id))

    fun reset() = byteArrayOf(OP_RESET.toByte())

    /** Split a body into DATA frames that each fit one acknowledged ATT write. */
    fun chunks(id: Int, body: ByteArray): List<ByteArray> {
        val frames = ArrayList<ByteArray>((body.size + DATA_PAYLOAD - 1) / DATA_PAYLOAD)
        var offset = 0
        while (offset < body.size) {
            val end = minOf(offset + DATA_PAYLOAD, body.size)
            frames.add(data(id, offset, body.copyOfRange(offset, end)))
            offset = end
        }
        return frames
    }

    /** Parsed phone frame. `error` is set instead of throwing: a malformed frame is normal traffic. */
    data class Frame(val op: Int, val id: Int = 0, val kind: Int = 0, val length: Int = 0, val crc: Int = 0,
        val offset: Int = 0, val chunk: ByteArray = ByteArray(0), val error: String? = null) {
        override fun equals(other: Any?) = this === other
        override fun hashCode() = System.identityHashCode(this)
    }

    /** Decode one frame the watch sent, for diagnostics and for the unit tests. */
    fun decode(frame: ByteArray): Frame {
        if (frame.isEmpty()) return Frame(0, error = "empty")
        val op = frame[0].toInt() and 0xff
        if (op == OP_RESET) return if (frame.size == 1) Frame(op) else Frame(op, error = "reset-length")
        if (frame.size < 5) return Frame(op, error = "short")
        val id = LinkBytes.read32(frame, 1)
        if (id == 0) return Frame(op, error = "id")
        return when (op) {
            OP_BEGIN -> if (frame.size != BEGIN_SIZE) Frame(op, id, error = "begin-length")
                else Frame(op, id, kind = frame[5].toInt() and 0xff, length = LinkBytes.read32(frame, 6), crc = LinkBytes.read32(frame, 10))
            OP_DATA -> if (frame.size <= DATA_HEADER || frame.size > ATT_PAYLOAD) Frame(op, id, error = "data-length")
                else Frame(op, id, offset = LinkBytes.read32(frame, 5), chunk = frame.copyOfRange(DATA_HEADER, frame.size))
            OP_END -> if (frame.size != END_SIZE) Frame(op, id, error = "end-length")
                else Frame(op, id, crc = LinkBytes.read32(frame, 5))
            OP_POLL -> if (frame.size != 10) Frame(op, id, error = "poll-length")
                else Frame(op, id, offset = LinkBytes.read32(frame, 5))
            OP_RELEASE -> if (frame.size != 5) Frame(op, id, error = "release-length") else Frame(op, id)
            else -> Frame(op, id, error = "op")
        }
    }
}
